.image-manager {
  width: 100%;
}

.toolbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 1rem;
  gap: 1rem;
}

.toolbar-section {
  display: flex;
  gap: 1rem;
  flex: 1;
}

.search-field {
  max-width: 300px;
}

.category-filter {
  max-width: 200px;
}

.toolbar-actions {
  display: flex;
  gap: 0.5rem;
}

.stats-bar {
  display: flex;
  gap: 2rem;
  padding: 1rem;
  background: #F8F9FA;
  border-radius: 8px;
  margin-bottom: 1.5rem;
}

.stat-item {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  color: #666666;
  font-size: 0.9rem;
}

.image-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 1.5rem;
}

.image-item {
  background: white;
  border-radius: 12px;
  border: 2px solid #E0E0E0;
  overflow: hidden;
  transition: all 0.3s ease;
  cursor: pointer;
  position: relative;
}

.image-item:hover {
  border-color: #667eea;
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.1);
}

.image-item.selected {
  border-color: #667eea;
  box-shadow: 0 0 0 2px rgba(102, 126, 234, 0.3);
}

.image-checkbox {
  position: absolute;
  top: 8px;
  left: 8px;
  z-index: 2;
  background: rgba(255, 255, 255, 0.9);
  border-radius: 4px;
}

.image-preview {
  position: relative;
  height: 200px;
  overflow: hidden;
}

.image-preview img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.image-overlay {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.5);
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  transition: opacity 0.3s ease;
}

.image-preview:hover .image-overlay {
  opacity: 1;
}

.image-info {
  padding: 1rem;
}

.image-name {
  font-weight: 500;
  color: #1A1A1A;
  margin-bottom: 0.5rem;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.image-meta {
  display: flex;
  justify-content: space-between;
  color: #666666;
  font-size: 0.875rem;
  margin-bottom: 0.5rem;
}

.image-tags {
  margin-top: 0.5rem;
}

.image-actions {
  display: flex;
  justify-content: flex-end;
  gap: 0.25rem;
  padding: 0.5rem 1rem;
  background: #F8F9FA;
  border-top: 1px solid #E0E0E0;
}

.empty-state {
  text-align: center;
  padding: 4rem 2rem;
  color: #666666;
}

.empty-state h3 {
  margin: 1rem 0 0.5rem;
  font-weight: 500;
}

.loading-state {
  text-align: center;
  padding: 4rem 2rem;
  color: #666666;
}

.loading-state p {
  margin-top: 1rem;
}

.preview-content {
  display: flex;
  gap: 2rem;
}

.preview-image {
  flex: 1;
  text-align: center;
}

.preview-image img {
  max-width: 100%;
  max-height: 400px;
  border-radius: 8px;
}

.preview-details {
  flex: 1;
}

.detail-item {
  margin-bottom: 1rem;
  padding-bottom: 0.5rem;
  border-bottom: 1px solid #E0E0E0;
}

.detail-item:last-child {
  border-bottom: none;
}

/* 响应式设计 */
@media (max-width: 768px) {
  .toolbar {
    flex-direction: column;
    align-items: stretch;
  }

  .toolbar-section {
    flex-direction: column;
  }

  .search-field,
  .category-filter {
    max-width: none;
  }

  .stats-bar {
    flex-direction: column;
    gap: 1rem;
  }

  .image-grid {
    grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
    gap: 1rem;
  }

  .preview-content {
    flex-direction: column;
  }
}

